create table if not exists public.workspace_leave_requests (
 id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade,
 leave_type text not null check (leave_type in ('annual','sick','family','unpaid','permission','other')), starts_on date not null, ends_on date not null, reason text,
 status text not null default 'pending' check (status in ('pending','approved','rejected','cancelled')),
 reviewed_by_profile_id uuid references public.profiles(id) on delete set null, reviewed_at timestamptz, review_comment text,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (ends_on >= starts_on));
create index if not exists workspace_leave_profile_dates_idx on public.workspace_leave_requests(profile_id, starts_on desc);
create index if not exists workspace_leave_status_dates_idx on public.workspace_leave_requests(status, starts_on);
create table if not exists public.workspace_objectives (
 id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade,
 title text not null check(length(trim(title)) between 1 and 200), description text, metric text, target_value numeric, current_value numeric, unit text,
 starts_on date, due_on date, status text not null default 'active' check(status in ('draft','active','at_risk','completed','cancelled')),
 created_by_profile_id uuid not null references public.profiles(id), updated_by_profile_id uuid references public.profiles(id),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (due_on is null or starts_on is null or due_on >= starts_on));
create index if not exists workspace_objectives_profile_idx on public.workspace_objectives(profile_id,status,due_on);
create table if not exists public.workspace_performance_reviews (
 id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade,
 reviewer_profile_id uuid not null references public.profiles(id), period_start date not null, period_end date not null,
 rating numeric check(rating between 0 and 5), strengths text, improvements text, next_steps text,
 status text not null default 'draft' check(status in ('draft','submitted','acknowledged')), acknowledged_at timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(period_end >= period_start));
create index if not exists workspace_reviews_profile_period_idx on public.workspace_performance_reviews(profile_id,period_end desc);
create table if not exists public.workspace_decision_audit (
 id bigint generated always as identity primary key, actor_profile_id uuid references public.profiles(id) on delete set null,
 action text not null, entity_type text not null, entity_id text, summary text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists workspace_decision_audit_created_idx on public.workspace_decision_audit(created_at desc);
create index if not exists workspace_decision_audit_entity_idx on public.workspace_decision_audit(entity_type,entity_id,created_at desc);
alter table public.workspace_leave_requests enable row level security;
alter table public.workspace_objectives enable row level security;
alter table public.workspace_performance_reviews enable row level security;
alter table public.workspace_decision_audit enable row level security;
create policy workspace_leave_read on public.workspace_leave_requests for select to authenticated using(profile_id=public.internal_current_profile_id() or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','ressources_humaines','admin','administrateur','pdg','dg','directeur_general','directeur général')));
create policy workspace_leave_insert_own on public.workspace_leave_requests for insert to authenticated with check(profile_id=public.internal_current_profile_id() and status='pending' and reviewed_by_profile_id is null);
create policy workspace_leave_update on public.workspace_leave_requests for update to authenticated using((profile_id=public.internal_current_profile_id() and status='pending') or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','ressources_humaines','admin','administrateur','pdg','dg','directeur_general','directeur général'))) with check((profile_id=public.internal_current_profile_id() and status in ('pending','cancelled')) or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','ressources_humaines','admin','administrateur','pdg','dg','directeur_general','directeur général')));
create policy workspace_objectives_read on public.workspace_objectives for select to authenticated using(profile_id=public.internal_current_profile_id() or created_by_profile_id=public.internal_current_profile_id() or exists(select 1 from public.workspace_reporting_lines rl where rl.profile_id=workspace_objectives.profile_id and rl.manager_profile_id=public.internal_current_profile_id() and rl.valid_to is null) or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','ressources_humaines','admin','administrateur','pdg','dg','directeur_general','directeur général')));
create policy workspace_objectives_manage on public.workspace_objectives for all to authenticated using(created_by_profile_id=public.internal_current_profile_id() or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','ressources_humaines','admin','administrateur','pdg','dg','directeur_general','directeur général'))) with check(created_by_profile_id=public.internal_current_profile_id() or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','ressources_humaines','admin','administrateur','pdg','dg','directeur_general','directeur général')));
create policy workspace_reviews_read on public.workspace_performance_reviews for select to authenticated using(profile_id=public.internal_current_profile_id() or reviewer_profile_id=public.internal_current_profile_id() or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','ressources_humaines','admin','administrateur','pdg','dg','directeur_general','directeur général')));
create policy workspace_reviews_manage on public.workspace_performance_reviews for all to authenticated using(reviewer_profile_id=public.internal_current_profile_id() or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','ressources_humaines','admin','administrateur','pdg','dg','directeur_general','directeur général'))) with check(reviewer_profile_id=public.internal_current_profile_id() or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','ressources_humaines','admin','administrateur','pdg','dg','directeur_general','directeur général')));
create policy workspace_audit_read on public.workspace_decision_audit for select to authenticated using(exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','ressources_humaines','admin','administrateur','pdg','dg','directeur_general','directeur général')));
revoke all on public.workspace_decision_audit from anon, authenticated; grant select on public.workspace_decision_audit to authenticated;
grant select,insert,update,delete on public.workspace_leave_requests,public.workspace_objectives,public.workspace_performance_reviews to authenticated;
revoke all on public.workspace_leave_requests,public.workspace_objectives,public.workspace_performance_reviews from anon;
